    # Check if p is collinear with a and b
    def is_collinear(p, a, b):
        # Cross product of vectors (b - a) and (p - a)
        # If cross product is zero, points are collinear
        return (b[0] - a[0]) * (p[1] - a[1]) == (b[1] - a[1]) * (p[0] - a[0])

