def is_convex_polygon(points):
    def cross_product(o, a, b):
        # Vector OA = (a[0] - o[0], a[1] - o[1])
        # Vector OB = (b[0] - o[0], b[1] - o[1])
        # Cross product OA x OB = (a[0] - o[0])*(b[1] - o[1]) - (a[1] - o[1])*(b[0] - o[0])
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Use the first three points to determine the direction (clockwise or counter-clockwise)
    prev = cross_product(points[0], points[1], points[2])
    if prev == 0:
        return False  # Collinear points, not a valid polygon

    for i in range(1, n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        curr = cross_product(o, a, b)
        if curr == 0:
            return False  # Collinear points, not convex
        if (prev < 0 and curr > 0) or (prev > 0 and curr < 0):
            return False  # Change in direction, not convex
        prev = curr

    return True
```

