def is_convex_polygon(points):
    def cross(o, a, b):
        # Returns the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    if all(cross(points[0], points[i], points[(i+1)%n]) == 0 for i in range(1, n-1)):
        return False

    # Check all consecutive triplets of points
    prev = cross(points[-2], points[-1], points[0])
    for i in range(1, n):
        curr = cross(points[i-1], points[i], points[(i+1)%n])
        if curr * prev < 0:
            return False  # Concave angle found
        prev = curr

    return True
```

