def equal_under_rotation(grid1, grid2):
    def rotate_90(matrix):
        return [list(row)[::-1] for row in zip(*matrix)]

    def rotate_180(matrix):
        return rotate_90(rotate_90(matrix))

    def rotate_270(matrix):
        return rotate_90(rotate_180(matrix))

    # Check if grids are already equal (0 degree rotation)
    if grid1 == grid2:
        return True

    # Generate all rotations of grid1 and compare
    rotated_90 = rotate_90(grid1)
    if rotated_90 == grid2:
        return True

    rotated_180 = rotate_180(grid1)
    if rotated_180 == grid2:
        return True

    rotated_270 = rotate_270(grid1)
    if rotated_270 == grid2:
        return True

    return False
```

