        # Rotate matrix 90 degrees clockwise
        return [list(row)[::-1] for row in zip(*matrix)]

    def rotate180(matrix):
        # Rotate matrix 180 degrees clockwise
        return rotate90(rotate90(matrix))

    def rotate270(matrix):
        # Rotate matrix 270 degrees clockwise
        return rotate90(rotate180(matrix))

    # Check all four rotations of grid1
    for i in range(4):
        if grid1 == grid2:
            return True
        grid1 = rotate90(grid1)

