def equal_under_rotation(grid1, grid2):
    def rotate_clockwise(grid):
        return [list(row)[::-1] for row in zip(*grid)]

    def rotate_90(grid):
        return rotate_clockwise(grid)

    def rotate_180(grid):
        return rotate_clockwise(rotate_clockwise(grid))

    def rotate_270(grid):
        return rotate_clockwise(rotate_clockwise(rotate_clockwise(grid)))

    # Check if grids are already equal (0 degrees rotation)
    if grid1 == grid2:
        return True

    # Check 90 degrees rotation
    rotated_90 = rotate_90(grid1)
    if rotated_90 == grid2:
        return True

    # Check 180 degrees rotation
    rotated_180 = rotate_180(grid1)
    if rotated_180 == grid2:
        return True

    # Check 270 degrees rotation
    rotated_270 = rotate_270(grid1)
    if rotated_270 == grid2:
        return True

    return False
