def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is considered valid

    rows = len(grid)
    cols = len(grid[0])

    # Determine the expected value based on the position (i, j)
    # The value at (i, j) should be different from (i-1, j), (i+1, j), (i, j-1), (i, j+1)
    # So for (i + j) even, it should be one value, and for odd, the other
    # We can use grid[0][0] as the reference for the first cell

    expected_even = grid[0][0]
    expected_odd = grid[0][1] if cols > 1 else (grid[1][0] if rows > 1 else None)

    # If there's only one cell, it's valid
    if rows == 1 and cols == 1:
        return True

    # If there's only one row or one column, check adjacent cells
    if rows == 1:
        for j in range(1, cols):
            if (j % 2 == 0 and grid[0][j] != expected_even) or (j % 2 == 1 and grid[0][j] != expected_odd):
                return False
    elif cols == 1:
        for i in range(1, rows):
            if (i % 2 == 0 and grid[i][0] != expected_even) or (i % 2 == 1 and grid[i][0] != expected_odd):
                return False
    else:
        # Check all cells
        for i in range(rows):
            for j in range(cols):
                if (i + j) % 2 == 0:
                    if grid[i][j] != expected_even:
                        return False
                else:
                    if grid[i][j] != expected_odd:
                        return False

    return True
