def parse_ini_line(line):
    # Strip leading and trailing whitespace from the line
    line = line.strip()
    # Split the line on '=' after stripping
    parts = line.split('=', 1)
    if len(parts) < 2:
        # If there's no '=', return the key as the whole line and empty value
        return (line, '')
    key, value = parts
    # Strip whitespace from key and value
    return (key.strip(), value.strip())
```

