def parse_simple_expr(s):
    # Find the operator index
    for i, char in enumerate(s):
        if char in "+-*/":
            operator_index = i
            break
    else:
        raise ValueError("Invalid expression: no operator found")

    # Split the expression into left and right operands
    left = s[:operator_index]
    right = s[operator_index+1:]

    # Convert operands to integers
    left_num = int(left)
    right_num = int(right)

    # Perform the operation
    if s[operator_index] == '+':
        return left_num + right_num
    elif s[operator_index] == '-':
        return left_num - right_num
    elif s[operator_index] == '*':
        return left_num * right_num
    elif s[operator_index] == '/':
        return left_num / right_num
```

