def parse_list_range_spec(spec):
    result = []
    tokens = spec.split(',')
    for token in tokens:
        if '-' in token:
            start, end = map(int, token.split('-'))
            result.extend(range(start, end + 1))
        else:
            result.append(int(token))
    return sorted(list(set(result)))
```

