    facing = 'N'

    # Mapping of directions and their changes in x and y
    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mapping: current direction -> left turn -> right turn
    turn_map = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            facing = turn_map[facing][cmd]
        elif cmd == 'F':
            dx, dy = direction_map[facing]
            x += dx
            y += dy

    return (x, y, facing)
```

