def traffic_light_log(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    cycle_length = red_ticks + green_ticks + yellow_ticks
    result = []

    for i in range(n_ticks):
        mod = i % cycle_length
        if mod < red_ticks:
            result.append("RED")
        elif mod < red_ticks + green_ticks:
            result.append("GREEN")
        elif mod < red_ticks + green_ticks + yellow_ticks:
            result.append("YELLOW")
        else:
