```python
def shopping_cart_total(events):
    cart = {}  # Dictionary to store items: {item: (quantity, price)}

    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                cart[item] = (cart[item][0] + qty, price)
            else:
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart:
                current_qty, price = cart[item]
                if current_qty > qty:
                    cart[item] = (current_qty - qty, price)
                else:
                    del cart[item]
        elif event[0] == "clear":
            cart.clear()

    total = sum(qty * price for qty, price in cart.values())
    return total
```

