def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)
    # Initialize robot's position and direction
    x, y = 0, 0
    direction = 'N'
    # Set of cleaned cells
    cleaned = set()
    cleaned.add((x, y))

    # Mapping of directions to coordinate changes
    direction_delta = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Mapping of direction changes for left and right turns
    turn_mapping = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = turn_mapping[direction][cmd]
        elif cmd == 'F':
            dx, dy = direction_delta[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add the new position to cleaned regardless of movement
            cleaned.add((x, y))

    return len(cleaned)
```

