def register_finalized_totals(events):
    transaction = []
    totals = []

    for event in events:
        if event[0] == "scan":
            price = event[1]
            transaction.append(price)
        elif event[0] == "void":
            if transaction:
                transaction.pop()
        elif event[0] == "pay":
            totals.append(sum(transaction))
            transaction = []

    return totals
