def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    red_a, green_a, yellow_a = durations_a
    red_b, green_b, yellow_b = durations_b
    cycle_a = red_a + green_a + yellow_a
    cycle_b = red_b + green_b + yellow_b

    count = 0

    for t in range(n_ticks):
        # Determine the state of light A at tick t
        mod_a = t % cycle_a
        state_a = None
        if 0 <= mod_a < red_a:
            state_a = "RED"
        elif red_a <= mod_a < red_a + green_a:
            state_a = "GREEN"
        elif red_a + green_a <= mod_a < cycle_a:
            state_a = "YELLOW"

        # Determine the state of light B at tick t
        mod_b = t % cycle_b
        state_b = None
        if 0 <= mod_b < red_b:
            state_b = "RED"
        elif red_b <= mod_b < red_b + green_b:
            state_b = "GREEN"
        elif red_b + green_b <= mod_b < cycle_b:
            state_b = "YELLOW"

        if state_a == "GREEN" and state_b == "GREEN":
            count += 1

    return count
```

