def is_point_on_segment(p, a, b):
    # Check if p is collinear with a and b
    # Cross product to check collinearity: (p - a) × (b - a) should be 0
    # Also, check if p lies between a and b (inclusive)
    # Using dot product to check if p is between a and b

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def dot(o, a, b):
        return (a[0] - o[0]) * (b[0] - o[0]) + (a[1] - o[1]) * (b[1] - o[1])

    # Check if cross product is zero (collinear)
    if cross(p, a, b) != 0:
        return False

    # Check if p lies between a and b (dot product is non-negative and <= length squared)
    if dot(p, a, b) < 0:
        return False

    # Check if p is not beyond b
    if dot(p, b, a) < 0:
        return False

    return True
```

