```python
def polygon_centroid(points):
    n = len(points)
    if n == 0:
        return (0.0, 0.0)
    sum_x = sum(x for x, y in points)
    sum_y = sum(y for x, y in points)
    cx = sum_x / n
    cy = sum_y / n
    return (cx, cy)
```

```python
def rotate_90_clockwise(grid):
    if not grid or not grid[0]:
        return []
    m, n = len(grid), len(grid[0])
    rotated = [[0] * m for _ in range(n)]
    for i in range(m):
        for j in range(n):
            rotated[j][m - 1 - i] = grid[i][j]
    return rotated
```

