def compare_semver(v1, v2):
    # Split the version strings into their components
    v1_parts = list(map(int, v1.split('.')))
    v2_parts = list(map(int, v2.split('.')))

    # Compare each component numerically
    for a, b in zip(v1_parts, v2_parts):
        if a < b:
            return -1
        elif a > b:
            return 1
    # If all components are equal, check if lengths are the same
    if len(v1_parts) == len(v2_parts):
        return 0
    else:
        # If one is a prefix of the other, the shorter one is considered older
        return -1 if len(v1_parts) < len(v2_parts) else 1
```

