def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme, rest = url.split('://', 1)

    # Split the rest into host and the remaining path/query
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        remaining = rest[host_end:]
        if remaining.startswith('/'):
            path_start = host_end
            query_start = remaining.find('?')
            if query_start == -1:
                path = remaining
                query = ''
            else:
                path = remaining[:query_start]
                query = remaining[query_start+1:]
        else:
            path = ''
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

