def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initial position and direction
    x, y = 0, 0
    direction = 'N'

    # Set of cleaned cells (including starting position)
    cleaned = set()
    cleaned.add((x, y))

    # Direction change mapping
    dir_map = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    # Movement mapping
    move_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = dir_map[direction][cmd]
        elif cmd == 'F':
            dx, dy = move_map[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add the new position to cleaned cells regardless of movement
            cleaned.add((x, y))

    return len(cleaned)
```

