def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)
    # Set to keep track of all cleaned cells
    cleaned = set()
    # Initial position and direction
    x, y = 0, 0
    direction = 'N'  # North

    # Add starting position to cleaned
    cleaned.add((x, y))

    # Direction mapping: current direction, turn left, turn right, move delta
    directions = {
        'N': {'L': 'W', 'R': 'E', 'move': (0, 1)},
        'E': {'L': 'N', 'R': 'S', 'move': (1, 0)},
        'S': {'L': 'E', 'R': 'W', 'move': (0, -1)},
        'W': {'L': 'S', 'R': 'N', 'move': (-1, 0)}
    }

    for cmd in commands:
        if cmd == 'L':
            direction = directions[direction]['L']
        elif cmd == 'R':
            direction = directions[direction]['R']
        elif cmd == 'F':
            dx, dy = directions[direction]['move']
            new_x = x + dx
            new_y = y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
