def grid_bot_fuel(commands, fuel):
    x, y = 0, 0
    for cmd in commands:
        if fuel <= 0:
            break
        if cmd == 'N':
            y += 1
        elif cmd == 'S':
            y -= 1
        elif cmd == 'E':
            x += 1
        elif cmd == 'W':
            x -= 1
        fuel -= 1
    return ((x, y), fuel)
```

